<?php use app\services\{Ui,Notifications};use yii\helpers\Html;$this->title='Bildirishnomalar';$reviewer=Yii::$app->user->identity->canReview(); ?>
<div class="page-heading"><div><span class="eyebrow">SHAXSIY KABINET</span><h1>Bildirishnomalar</h1><p><?= $reviewer?'Sizning bosqichingizga kelgan arizalar va o‘z arizalaringiz haqidagi so‘nggi 100 ta xabar.':'Arizalaringiz yaratilishi, yuborilishi va tekshiruv qarorlari haqidagi so‘nggi 100 ta xabar.' ?></p></div><?php if($reviewer): ?><?= Html::a('Tekshiruv navbati →',['kpi/applications','queue'=>1],['class'=>'button secondary']) ?><?php endif ?></div>
<section class="card"><?php if(!$rows): ?><?= Ui::empty($reviewer?'Bosqichingizga ariza kelganda yoki o‘z arizangiz holati o‘zgarganda xabar shu yerda ko‘rinadi.':'Ariza yaratganingizda va uning holati o‘zgarganda xabarlar shu yerda ko‘rinadi.') ?><?php else: ?><ol class="timeline"><?php foreach($rows as $row): ?><li><div><?= Html::a(Ui::h($row['title']),['kpi/view','id'=>$row['application_id']],['class'=>'text-link']) ?><span class="muted"><?= date('d.m.Y H:i',$row['created_at']) ?></span><?php if($row['unread']): ?><span class="badge review">Yangi</span><?php endif ?></div>
<?php if($row['is_assignment']):$steps=json_decode($row['route_snapshot']??'[]',true);$stage=$steps[(int)$row['current_step']]['name']??''; ?><p><b>Tekshirish uchun yangi ariza</b> · <?= Ui::h($row['employee']) ?></p><p><?= Ui::h($stage) ?> — ariza sizning tekshiruv navbatingizda.</p><?= Html::a('Arizani tekshirish →',['kpi/view','id'=>$row['application_id']],['class'=>'button secondary small']) ?>
<?php else: ?><p><b><?= Ui::h(Notifications::LABELS[$row['action']]??$row['action']) ?></b> · <?= Ui::h($row['actor']) ?></p><p><?= Ui::h($row['reason']) ?></p><?php endif ?>
<small>Arizaning hozirgi holati: <?= Ui::status($row['status']) ?></small></li><?php endforeach ?></ol><?php endif ?></section>
